<?php $title='Dépenses & trésorerie'; $subtitle='Suivez les sorties et les encaissements de votre salle.'; $section='finance'; require __DIR__.'/management_header.php'; ?>
<details class="card form-card" <?= $error ? 'open' : '' ?>><summary>+ Enregistrer une dépense</summary><form method="post" action="finance" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><label>Date de paiement *<input type="date" name="expense_date" value="<?= e($_POST['expense_date'] ?? date('Y-m-d')) ?>" max="<?= date('Y-m-d') ?>" required></label><label>Catégorie *<select name="category" required><?php foreach (['loyer'=>'Loyer','salaires'=>'Salaires','électricité'=>'Électricité','eau'=>'Eau','maintenance'=>'Maintenance','fournitures'=>'Fournitures','marketing'=>'Marketing','autre'=>'Autre'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($_POST['category'] ?? '')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Description *<input name="description" maxlength="500" value="<?= e($_POST['description'] ?? '') ?>" required></label><label>Montant (DT) *<input type="number" name="amount" min="0.001" max="9999999.999" step="0.001" value="<?= e($_POST['amount'] ?? '') ?>" required></label><label>Moyen de paiement *<select name="method"><?php foreach (['espèces','chèque','virement','D17','Flouci','carte bancaire'] as $method): ?><option value="<?= e($method) ?>" <?= ($_POST['method'] ?? '')===$method ? 'selected' : '' ?>><?= e(ucfirst($method)) ?></option><?php endforeach; ?></select></label><p class="form-hint">Enregistrez uniquement les dépenses effectivement payées. Les coûts de maintenance ne sont pas ajoutés automatiquement.</p><div class="form-actions"><button class="primary">Enregistrer la dépense</button></div></form></details>
<section class="card management-table"><div class="card-head"><div><h3>Bilan de trésorerie</h3><p>Encaissements et dépenses du mois sélectionné, en dinars tunisiens</p></div></div><form action="finance" class="search-form" method="get"><label for="finance-month">Mois</label><input type="month" id="finance-month" name="month" min="1900-01" max="2099-12" value="<?= e($month) ?>" required><button class="primary">Afficher</button></form><div class="finance-summary"><div><span>Abonnements nets</span><strong><?= e(dt($subscriptionTotal)) ?></strong></div><div><span>Ventes boutique</span><strong><?= e(dt($shopTotal)) ?></strong></div><div><span>Dépenses payées</span><strong><?= e(dt($expenseTotal)) ?></strong></div><div><span>Solde de trésorerie</span><strong><?= e(dt((float)$subscriptionTotal+(float)$shopTotal-(float)$expenseTotal)) ?></strong></div></div><p class="form-hint">Solde = encaissements d’abonnement − remboursements + ventes boutique − dépenses payées. Ce n’est pas un bilan comptable ni un résultat fiscal ; TVA et timbre ne sont pas calculés.</p></section>
<section class="card management-table"><div class="card-head"><div><h3>Dépenses du mois</h3><p><?= $total ?> dépense(s) · <?= e($month) ?></p></div><a class="text-link" href="finance_export?month=<?= e($month) ?>">Exporter en CSV ↓</a></div><div class="cash-methods"><?php foreach ($categories as $category): ?><div><span><?= e(ucfirst($category['category'])) ?></span><strong><?= e(dt($category['total'])) ?></strong></div><?php endforeach; ?></div><div class="table-scroll"><table><thead><tr><th>DATE</th><th>CATÉGORIE</th><th>DESCRIPTION</th><th>MOYEN</th><th>MONTANT</th><th>SAISI PAR</th></tr></thead><tbody><?php foreach ($expenses as $expense): ?><tr><td><?= e(date('d/m/Y',strtotime($expense['expense_date']))) ?></td><td><?= e(ucfirst($expense['category'])) ?></td><td class="intervention-description"><?= e($expense['description']) ?></td><td><?= e(ucfirst($expense['method'])) ?></td><td><?= e(dt($expense['amount'])) ?></td><td><?= e($expense['author'] ?: '—') ?></td></tr><?php endforeach; ?><?php if (!$expenses): ?><tr><td colspan="6" class="empty">Aucune dépense enregistrée pour ce mois.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="finance?month=<?= e($month) ?>&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="finance?month=<?= e($month) ?>&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div></section>
